import React from 'react';
import { Grommet, Box, Tabs, Tab, Text } from 'grommet';
import { hpe } from 'grommet-theme-hpe';

const LongContent = () => (
  <Box pad="small">
    {[...Array(40)].map((_, i) => (
      <Text key={i} margin={{ bottom: 'small' }}>
        Line {i + 1} – This is a long content line to force scrolling.
      </Text>
    ))}
  </Box>
);

export const App = () => (
  <Grommet theme={hpe} full>
    {/*
      1. Outer Box has fixed height and overflow so that tabs’ content scrolls
      2. Tabs header should have its underline stick to the bottom
    */}
    <Box height="medium" border={{ color: 'border' }} overflow="auto">
      <Tabs flex={false}>
        <Tab title="Title 1">
          <LongContent />
        </Tab>
        <Tab title="Title 2">
          <LongContent />
        </Tab>
      </Tabs>
    </Box>
  </Grommet>
);
